      if nil == sb || (!options.fflag && !options.cflag && nil == (sb = try? FileMetadata(for: ps, followSymlinks: false), sb).1 ) {

        /* lets try <path>.gz if we're decompressing */
        if options.dflag && !second && errno == ENOENT {
