  /* compress/decompress a file */
  func handle_file(_ file : FilePath, _ sbp : FileMetadata) {
    var usize : UInt = 0
    var gsize : UInt = 0

    r.infile = file
    r.infile_total = sbp.size

    if options.dflag {
      guard let usize = file_uncompress(file) else {
        if options.vflag && options.tflag {
          print_test(file, false)
        }
        return
      }

      if options.vflag && options.tflag {
        print_test(file, true)
      }
      gsize = sbp.size
    } else {
      guard let gsize = file_compress(file) else {
        return;
      }
      usize = sbp.size
    }

    r.infile = nil
    r.infile_total = 0
    r.infile_current = 0

    if (options.vflag && !options.tflag) {
      print_verbage(file, options.cflag ? nil : r.outfile?.string, usize, gsize)
    }

  }

  /* this is used with -r to recursively descend directories */
  func handle_dir(_ dir : FilePath) {
    guard let fts = try? FTSWalker(path: [dir.string], options: [.PHYSICAL,  .NOCHDIR], sort: nil) else {
      warn("couldn't fts_open \(dir)")
      return
    }

    for entry in fts {
      switch entry.info {
        case .D, .DP:
          continue

        case .DNR, .ERR, .NS:
          maybe_warn(entry.path)
          continue
        case .F:
          handle_file(FilePath(entry.path), entry.statp)
        default:
          // FIXME: what should I do here?
          continue
      }
    }
    if (errno != 0) {
      warn("error with fts_read \(dir)")
    }
  }

  /* print a ratio - size reduction as a fraction of uncompressed size */
  func print_ratio(_ inxx : UInt, _ out : UInt, _ wherex : FileDescriptor) {
/*    int percent10;  /* 10 * percent */
    off_t diff;
    char buff[8];
    int len;
*/
    var inx = Int(inxx)
    var percent10 : Int
    var diff = Int(inx) - Int(out)/2
    if inx == 0 && out == 0 {
      percent10 = 0
    }
    else if diff < 0 {
      /*
       * Output is more than double size of input! print -99.9%
       * Quite possibly we've failed to get the original size.
       */
      percent10 = -999
    }
    else {
      /*
       * We only need 12 bits of result from the final division,
       * so reduce the values until a 32bit division will suffice.
       */
      while inx > 0x100000 {
        diff >>= 1
        inx >>= 1
      }
      if inx != 0 {
        percent10 = Int((diff * 2000) / inx - 1000)
      }
      else {
        percent10 = 0
      }
    }

    var buff = cFormat("%2.2d.", percent10)
    /* Move the '.' to before the last digit */
    buff = String(buff.dropLast(2) + "." + buff.dropLast().suffix(1))
    var wherexx = wherex
    print(buff.leftPad(toLength: 5), terminator: "%", to: &wherexx)
  }

  /* print compression statistics, and the new name (if there is one!) */
  func print_verbage(_ file : FilePath?, _ nfile : String?, _ usize : UInt, _ gsize : UInt) {
    var stderr = FileDescriptor.standardError
    if let file {
      print("\(file.string):\(file.string.count < 7 ? "\t\t" : "\t")  ", terminator: "", to: &stderr)
    }
    print_ratio(usize, gsize, stderr);
    if let nfile {
      print(" -- replaced with \(nfile)", terminator: "")
    }
    print("", to: &stderr)
  }

  /* print test results */
  func print_test(_ file : FilePath, _ ok : Bool) {
//    var stderr = FileDescriptor.standardError
    if r.exit_value == 0 && !ok {
      r.exit_value = 1
    }
    print("\(file.string):\(file.string.count < 7 ? "\t\t" : "\t")  \(ok ? "OK" : "NOT OK")")
  }

  /* print a file's info ala --list */
  /* eg:
   compressed uncompressed  ratio uncompressed_name
   354841      1679360  78.8% /usr/pkgsrc/distfiles/libglade-2.0.1.tar
   */
  func print_list(_ fd : FileDescriptor?, _ outx : UInt, _ outfile : FilePath, _ ts : DateTime) {

    // FIXME: These vars were static
    var in_tot : UInt = 0
    var out_tot : UInt = 0

    var crc : UInt32 = 0
    var inx : UInt = 0
    var out : UInt = outx
    if r.firstPrint {
      r.firstPrint = false
      if options.vflag {
        print("method  crc     date  time  ", terminator: "")
      }

      if !options.qflag {
        print("  compressed uncompressed  ratio uncompressed_name")
      }
    }


    /* print totals? */

    if let fd {
      /* read the last 4 bytes - this is the uncompressed size */
      if let rv = try? fd.seek(offset: -8, from: .end) {
        guard let buf = try? fd.readUpToCount(8) else {
          maybe_warn("read of uncompressed size")
          return
        }
        if buf.count != 8 {
          maybe_warnx("read of uncompressed size")
        }

        else {
          let usize = le32dec(buf[4...])
          inx = UInt(usize)
          crc = le32dec(buf)

        }
      }
    } else {
      inx = in_tot
      out = out_tot
    }

    if options.vflag && fd == nil {
      print("                            ", terminator: "")
    }
    else if (options.vflag) {
      var b = ts.secs
      let date = String(cString: Darwin.ctime(&b))
      let dd = date.dropFirst(4).prefix(11)
      /* skip the day, 1/100th second, and year */
      let a = cFormat("%08x", crc)
      print("defla \(a) \(dd) ", terminator: "")
    }
    in_tot += inx
    out_tot += out
    print_list_out(out, inx, outfile)
  }

  func print_list_out(_ out : UInt, _ inx : UInt, _ outfile : FilePath) {
    let a = cFormat("%12llu", out)
    let b = cFormat("%12llu", inx)
    print("\(a) \(b) ", terminator: "")
    print_ratio(inx, out, FileDescriptor.standardOutput)
    print(" \(outfile)")
  }

